import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    a = [x - 1 for x in data[2:]]

    indeg = [0] * n
    for v in a:
        indeg[v] += 1
    stack = [i for i in range(n) if indeg[i] == 0]
    for v in stack:
        w = a[v]
        indeg[w] -= 1
        if indeg[w] == 0:
            stack.append(w)

    is_cycle = [x > 0 for x in indeg]
    comp = [-1] * n
    components = []
    for i in range(n):
        if is_cycle[i] and comp[i] < 0:
            cid = len(components)
            cycle_nodes = []
            v = i
            while comp[v] < 0:
                comp[v] = cid
                cycle_nodes.append(v)
                v = a[v]
            components.append(cycle_nodes)

    children = [[] for _ in range(n)]
    roots_by_comp = [[] for _ in components]
    for v in range(n):
        if not is_cycle[v]:
            p = a[v]
            if is_cycle[p]:
                roots_by_comp[comp[p]].append(v)
            else:
                children[p].append(v)

    answer = 1
    # Components are independent.  Process one at a time to keep memory small.
    for cid in range(len(components)):
        component_dp = [1] * m
        acc = [None] * n
        for root in roots_by_comp[cid]:
            events = [(root, 0)]
            while events:
                v, typ = events.pop()
                if typ == 0:
                    acc[v] = None
                    events.append((v, 1))
                    for u in children[v]:
                        events.append((u, 0))
                else:
                    vec = acc[v]
                    if vec is None:
                        vec = [1] * m
                    s = 0
                    for k in range(m):
                        s = (s + vec[k]) % MOD
                        vec[k] = s
                    p = a[v]
                    if is_cycle[p]:
                        target = component_dp
                    else:
                        target = acc[p]
                        if target is None:
                            target = [1] * m
                            acc[p] = target
                    for k in range(m):
                        target[k] = target[k] * vec[k] % MOD
                    acc[v] = None
        answer = answer * (sum(component_dp) % MOD) % MOD

    print(answer)

if __name__ == '__main__':
    main()

