import sys

MOD = 998244353

def factor(n):
    res = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            res[d] = res.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        res[n] = res.get(n, 0) + 1
    return res

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]
    fact = [factor(x) for x in a]
    primes = set()
    for f in fact:
        primes.update(f)

    answer = 1
    for p in primes:
        exponents = [f.get(p, 0) for f in fact]
        dp = [1]
        max_y = 0
        positions = 1

        for e in exponents:
            powers = [1] * (max_y + e + 1)
            for j in range(1, len(powers)):
                powers[j] = powers[j - 1] * p % MOD
            nxt = [0] * (max_y + e + 1)

            if e == 0:
                for y, value in enumerate(dp):
                    nxt[y] = value * powers[y] % MOD
            else:
                for y, value in enumerate(dp):
                    # Put the whole p-part on the numerator of this edge.
                    hi = y + e
                    nxt[hi] = (nxt[hi] + value * powers[hi]) % MOD

                    # Put the whole p-part on the denominator.
                    lo = y - e
                    if lo >= 0:
                        nxt[lo] = (nxt[lo] + value * powers[lo]) % MOD
                    else:
                        # The new point creates a lower minimum; all previous
                        # normalized exponents are shifted upward by -lo.
                        nxt[0] = (nxt[0] + value * pow(p, (-lo) * positions, MOD)) % MOD

            dp = nxt
            max_y += e
            positions += 1

        answer = answer * (sum(dp) % MOD) % MOD

    print(answer)

if __name__ == "__main__":
    main()

