    values = data[1:1 + n]
    limit = max(values)

    spf = [0] * (limit + 1)
    for i in range(2, limit + 1):
        if spf[i] == 0:
            spf[i] = i
            if i * i <= limit:
                for j in range(i * i, limit + 1, i):
                    if spf[j] == 0:
                        spf[j] = i

    nim_sum = 0
    for value in values:
        factors = 0
        while value > 1:
            value //= spf[value]
            factors += 1
        nim_sum ^= factors

