import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n = next(it)
    q = next(it)

    parent = list(range(n + 1))
    size = [1] * (n + 1)
    left = list(range(n + 1))
    right = list(range(n + 1))
    color = list(range(n + 1))
    count = [0] * (n + 1)
    for i in range(1, n + 1):
        count[i] = 1

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def merge(a, b):
        a = find(a)
        b = find(b)
        if a == b:
            return a
        if size[a] < size[b]:
            a, b = b, a
        parent[b] = a
        size[a] += size[b]
        if left[b] < left[a]:
            left[a] = left[b]
        if right[b] > right[a]:
            right[a] = right[b]
        return a

    answer = []
    for _ in range(q):
        typ = next(it)
        if typ == 1:
            x = next(it)
            c = next(it)
            root = find(x)
            old = color[root]
            if old != c:
                count[old] -= size[root]
                count[c] += size[root]
                color[root] = c

            if left[root] > 1:
                other = find(left[root] - 1)
                if color[other] == c:
                    root = merge(root, other)
            if right[root] < n:
                other = find(right[root] + 1)
                if color[other] == c:
                    root = merge(root, other)
        else:
            answer.append(str(count[next(it)]))

    sys.stdout.write("\n".join(answer))

if __name__ == "__main__":
    main()

