from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        for idx, (x, y) in enumerate(conflictingPairs):
            a, b = (x, y) if x < y else (y, x)
            by_right[b].append((a, idx))

        # The two largest left endpoints among pairs whose right endpoint
        # has been reached.  Keeping the pair indices handles equal values.
        first = (0, -1)
        second = (0, -1)
        gains = [0] * len(conflictingPairs)
        total = 0

        for right in range(1, n + 1):
            for left, idx in by_right[right]:
                if left > first[0]:
                    second, first = first, (left, idx)
                elif left > second[0]:
                    second = (left, idx)

            total += right - first[0]
            if first[0] > second[0]:
                gains[first[1]] += first[0] - second[0]

        return total + max(gains)

