class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        # dp[k] is the number of possibilities after processing the current
        # performers, with exactly k nonempty stages.
        dp = [0] * (x + 1)
        dp[0] = 1

        for i in range(n):
            nxt = [0] * (x + 1)
            for k in range(min(i, x) + 1):
                ways = dp[k]
                if not ways:
                    continue
                # Put the new performer into one of the k existing stages.
                nxt[k] = (nxt[k] + ways * k) % MOD
                # Put them into one of the x-k empty stages and score that band.
                if k < x:
                    nxt[k + 1] = (nxt[k + 1] + ways * (x - k) * y) % MOD
            dp = nxt

        return sum(dp) % MOD

