class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        length = len(s)

        # Binomial coefficients count suffixes having a prescribed number
        # of set bits.
        comb = [[0] * (length + 1) for _ in range(length + 1)]
        for i in range(length + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # If x has c set bits, its first operation produces c.  Determine
        # which values of c reach 1 within the remaining operations.
        good = []
        for c in range(1, length + 1):
            value = c
            steps = 0
            while value != 1:
                value = value.bit_count()
                steps += 1
            if steps <= k - 1:
                good.append(c)

        answer = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = length - i - 1
                # Make this bit zero; the suffix can then be arbitrary,
                # provided the total popcount is one of the good values.
                for total in good:
                    needed = total - prefix_ones
                    if 0 <= needed <= remaining:
                        answer += comb[remaining][needed]
                prefix_ones += 1
        return answer % MOD

