import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    at = 2
    for _ in range(m):
        u, v = data[at] - 1, data[at + 1] - 1
        at += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    rank = 0
    pivots = []
    for col in range(n):
        found = -1
        for i in range(rank, n):
            if (rows[i] >> col) & 1:
                found = i
                break
        if found < 0:
            continue
        rows[rank], rows[found] = rows[found], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> col) & 1):
                rows[i] ^= rows[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]
    values = [0] * n
    for bit, f in enumerate(free):
        vector = 1 << f
        for i, p in enumerate(pivots):
            if (rows[i] >> f) & 1:
                vector |= 1 << p
        for v in range(n):
            if (vector >> v) & 1:
                values[v] |= 1 << bit

    if any(x == 0 for x in values):
        print("No")
    else:
        print("Yes")
        print(*values)

if __name__ == "__main__":
    main()

