class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half = (n + 1) // 2
        coeff = []
        for i in range(half):
            j = n - 1 - i
            left = pow(10, i, k)
            if i == j:
                coeff.append(left)
            else:
                coeff.append((left + pow(10, j, k)) % k)

        # dp[i][r] says that positions i..half-1 can contribute residue r.
        dp = [bytearray(k) for _ in range(half + 1)]
        dp[half][0] = 1
        for i in range(half - 1, -1, -1):
            cur = dp[i]
            nxt = dp[i + 1]
            c = coeff[i]
            for digit in range(10):
                add = digit * c
                for residue in range(k):
                    if nxt[residue]:
                        cur[(add + residue) % k] = 1

        chosen = []
        residue = 0
        for i, c in enumerate(coeff):
            lowest = 1 if i == 0 else 0
            for digit in range(9, lowest - 1, -1):
                needed = (-(residue + digit * c)) % k
                if dp[i + 1][needed]:
                    chosen.append(str(digit))
                    residue = (residue + digit * c) % k
                    break

        prefix = ''.join(chosen)
        if n % 2:
            return prefix + prefix[-2::-1]
        return prefix + prefix[::-1]

