from array import array

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)

        # ng[i] is the first position to the right whose value is greater
        # than nums[i].  Equal values need not start a new prefix maximum.
        ng = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            if stack:
                ng[i] = stack[-1]
            stack.append(i)

        # A jump i -> ng[i] skips a range having nums[i] as its prefix max.
        # Binary lifting also stores the sum of these prefix maxima.
        up = [array('i', ng)]
        gain = [array('q', (nums[i] * (ng[i] - i) for i in range(n)))]
        while (1 << len(up)) <= n:
            old_up = up[-1]
            old_gain = gain[-1]
            new_up = array('i', [0]) * n
            new_gain = array('q', [0]) * n
            for i in range(n):
                j = old_up[i]
                if j < n:
                    new_up[i] = old_up[j]
                    new_gain[i] = old_gain[i] + old_gain[j]
                else:
                    new_up[i] = n
                    new_gain[i] = old_gain[i]
            up.append(new_up)
            gain.append(new_gain)

        prefix = [0]
        for x in nums:
            prefix.append(prefix[-1] + x)

        def cost(left: int, right: int) -> int:
            pos = left
            target_sum = 0
            for level in range(len(up) - 1, -1, -1):
                nxt = up[level][pos]
                if nxt <= right:
                    target_sum += gain[level][pos]
                    pos = nxt
            target_sum += nums[pos] * (right - pos + 1)
            return target_sum - (prefix[right + 1] - prefix[left])

        answer = 0
        for right in range(n):
            lo, hi = 0, right + 1
            while lo < hi:
                mid = (lo + hi) // 2
                if cost(mid, right) <= k:
                    hi = mid
                else:
                    lo = mid + 1
            answer += right - lo + 1
        return answer

