from array import array

class Solution:
    def maximumSubarrayXor(self, nums, queries):
        n = len(nums)
        table = array('I', [0]) * (n * n)

        for i, value in enumerate(nums):
            table[i * n + i] = value

        # Score of [i, j] is score([i, j-1]) XOR score([i+1, j]).
        for i in range(n - 2, -1, -1):
            row = i * n
            next_row = (i + 1) * n
            for j in range(i + 1, n):
                table[row + j] = table[row + j - 1] ^ table[next_row + j]

        # Turn the score table into the maximum-score table in place.
        for i in range(n - 2, -1, -1):
            row = i * n
            next_row = (i + 1) * n
            for j in range(i + 1, n):
                best = table[row + j]
                below = table[next_row + j]
                left = table[row + j - 1]
                if below > best:
                    best = below
                if left > best:
                    best = left
                table[row + j] = best

        return [table[l * n + r] for l, r in queries]

