class Solution:
    def makeStringGood(self, s: str) -> int:
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - 97] += 1

        n = len(s)
        answer = n  # deleting every character is always possible
        INF = 10**9

        # Try every positive common frequency.  For each frequency, the
        # two states indicate whether the current letter is retained.
        for k in range(1, n + 1):
            dp = [0, INF]
            for i, cnt in enumerate(counts):
                ndp = [INF, INF]
                for previous in (0, 1):
                    for current in (0, 1):
                        target = k if current else 0
                        cost = dp[previous] + abs(cnt - target)
                        if i:
                            previous_target = k if previous else 0
                            # An adjacent change replaces one deletion and
                            # one insertion, saving one operation.
                            movable = max(counts[i - 1] - previous_target, 0)
                            needed = max(target - cnt, 0)
                            cost -= min(movable, needed)
                        if cost < ndp[current]:
                            ndp[current] = cost
                dp = ndp
            answer = min(answer, dp[0], dp[1])
        return answer

