import sys
from functools import lru_cache


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m, l = data[:3]
    values = data[3:]
    total = n + m + l
    full = (1 << total) - 1
    initial_t = (1 << n) - 1
    initial_a = ((1 << m) - 1) << n

    @lru_cache(maxsize=None)
    def winning(t_hand, a_hand, player):
        hand = t_hand if player == 0 else a_hand
        if hand == 0:
            return False

        table = full ^ (t_hand | a_hand)
        cards = hand
        while cards:
            played_bit = cards & -cards
            cards -= played_bit
            played = played_bit.bit_length() - 1

            new_t = t_hand
            new_a = a_hand
            if player == 0:
                new_t -= played_bit
            else:
                new_a -= played_bit

            # Play the card without taking another card.
            if not winning(new_t, new_a, 1 - player):
                return True

            # Or take any table card with a strictly smaller number.
            candidates = table
            while candidates:
                taken_bit = candidates & -candidates
                candidates -= taken_bit
                taken = taken_bit.bit_length() - 1
                if values[taken] < values[played]:
                    if player == 0:
                        loses = winning(new_t | taken_bit, new_a, 1)
                    else:
                        loses = winning(new_t, new_a | taken_bit, 0)
                    if not loses:
                        return True

        return False

    print("Takahashi" if winning(initial_t, initial_a, 0) else "Aoki")


if __name__ == "__main__":
    main()

