import heapq

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    g = [[] for _ in range(n)]
    j = 1
    for _ in range(n - 1):
        u, v, w = data[j] - 1, data[j + 1] - 1, data[j + 2]
        j += 3
        g[u].append((v, w))
        g[v].append((u, w))

    parent = [-1] * n
    pedge = [0] * n
    order = [0]
    for u in order:
        for v, w in g[u]:
            if v != parent[u]:
                parent[v] = u
                pedge[v] = w
                order.append(v)

    height = [0] * n
    heavy = [-1] * n
    for u in reversed(order):
        for v, w in g[u]:
            if parent[v] == u and w + height[v] > height[u]:
                height[u] = w + height[v]
                heavy[u] = v

    heap = []
    for v, w in g[0]:
        heapq.heappush(heap, (-(w + height[v]), v))

    gains = []
    while heap:
        neg, u = heapq.heappop(heap)
        gains.append(-neg)
        while True:
            hv = heavy[u]
            for v, w in g[u]:
                if parent[v] == u and v != hv:
                    heapq.heappush(heap, (-(w + height[v]), v))
            if hv == -1:
                break
            u = hv

    total = 2 * sum(pedge)
    cur = 0
    out = []
    for k in range(1, n + 1):
        if k <= len(gains):
            cur += gains[k - 1]
            out.append(str(2 * cur))
        else:
            out.append(str(total))
    sys.stdout.write('\n'.join(out))

