import sys
import heapq

def values(seq):
    low = []          # max-heap, stored negated
    high = []         # min-heap
    sum_low = sum_high = 0
    result = [0]
    for x in seq:
        if not low or x <= -low[0]:
            heapq.heappush(low, -x)
            sum_low += x
        else:
            heapq.heappush(high, x)
            sum_high += x
        if len(low) > len(high) + 1:
            y = -heapq.heappop(low)
            sum_low -= y
            heapq.heappush(high, y)
            sum_high += y
        elif len(high) > len(low):
            y = heapq.heappop(high)
            sum_high -= y
            heapq.heappush(low, -y)
            sum_low += y
        if len(low) == len(high):
            result.append(sum_high - sum_low)
        else:
            result.append(None)
    return result

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]
    prefix = values(a)
    if n % 2 == 0:
        print(prefix[n])
    else:
        suffix_lengths = values(reversed(a))
        # The unmatched element is at an even zero-based position.
        print(max(prefix[s] + suffix_lengths[n - s - 1]
                  for s in range(0, n + 1, 2)))

