import sys

MOD = 998244353

def solve_case(H, W, s):
    col_a = [0] * W
    row_ok = True
    for row in s:
        cnt = 0
        for j, ch in enumerate(row):
            if ch == 'A':
                cnt ^= 1
                col_a[j] ^= 1
        if cnt:
            row_ok = False
    if not row_ok or any(col_a):
        return 0

    n = H + W
    parent = list(range(n))
    size = [1] * n
    # xor_to_parent[v] is value(v) xor value(parent[v])
    xor_to_parent = [0] * n

    def find(v):
        if parent[v] != v:
            q = parent[v]
            parent[v] = find(q)
            xor_to_parent[v] ^= xor_to_parent[q]
        return parent[v]

    col_prefix = [0] * W
    components = n

    for i in range(H):
        row_prefix = 0
        row = s[i]
        for j, ch in enumerate(row):
            old_col_prefix = col_prefix[j]
            is_a = (ch == 'A')
            if is_a:
                col_prefix[j] ^= 1
            if ch == 'B':
                a = find(i)
                b = find(H + j)
                # row_value xor column_value, from the B-tile condition
                required = 1 ^ row_prefix ^ old_col_prefix
                if a == b:
                    if (xor_to_parent[i] ^ xor_to_parent[H + j]) != required:
                        return 0
                else:
                    # At this point xor_to_parent[i] and ...[j] give
                    # values relative to their respective roots.
                    relation = required ^ xor_to_parent[i] ^ xor_to_parent[H + j]
                    if size[a] > size[b]:
                        parent[b] = a
                        xor_to_parent[b] = relation
                        size[a] += size[b]
                    else:
                        parent[a] = b
                        xor_to_parent[a] = relation
                        size[b] += size[a]
                    components -= 1
            if is_a:
                row_prefix ^= 1

    return pow(2, components, MOD)

def main():
    data = sys.stdin.buffer
    t = int(data.readline())
    ans = []
    for _ in range(t):
        H, W = map(int, data.readline().split())
        s = [data.readline().strip().decode() for _ in range(H)]
        ans.append(str(solve_case(H, W, s)))
    sys.stdout.write('\n'.join(ans))

if __name__ == '__main__':
    main()

