class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        a, b, c = p.split('*')

        def occurrences(t):
            m = len(t)
            hit = bytearray(n + 1)
            if m == 0:
                hit[:] = b'\x01' * (n + 1)
                return hit

            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j

            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    hit[i - m + 1] = 1
                    j = pi[j - 1]
            return hit

        def next_occurrence(hit):
            nxt = [n + 1] * (n + 2)
            for i in range(n, -1, -1):
                nxt[i] = i if hit[i] else nxt[i + 1]
            return nxt

        ha = occurrences(a)
        hb = occurrences(b)
        hc = occurrences(c)
        next_b = next_occurrence(hb)
        next_c = next_occurrence(hc)

        la, lb, lc = len(a), len(b), len(c)
        best = n + 1
        for start in range(n + 1):
            if not ha[start]:
                continue
            after_a = start + la
            b_start = next_b[after_a] if after_a <= n else n + 1
            if b_start > n:
                continue
            after_b = b_start + lb
            c_start = next_c[after_b] if after_b <= n else n + 1
            if c_start <= n:
                best = min(best, c_start + lc - start)

        return -1 if best == n + 1 else best

