    if not data:
        return
    n, m = data[0], data[1]
    graph = [[] for _ in range(n)]
    p = 2
    for _ in range(m):
        x, y, z = data[p] - 1, data[p + 1] - 1, data[p + 2]
        p += 3
        graph[x].append((y, z))
        graph[y].append((x, z))

    potential = [-1] * n
    answer = [0] * n
    for start in range(n):
        if potential[start] != -1:
            continue
        potential[start] = 0
        stack = [start]
        component = []
        ones = [0] * 30
        valid = True
        while stack:
            v = stack.pop()
            value = potential[v]
            component.append(v)
            for bit in range(30):
                ones[bit] += (value >> bit) & 1
            for w, z in graph[v]:
                expected = value ^ z
                if potential[w] == -1:
                    potential[w] = expected
                    stack.append(w)
