                    valid = False
        if not valid:
            print(-1)
            return
        size = len(component)
        shift = 0
        for bit in range(30):
            if 2 * ones[bit] > size:
                shift |= 1 << bit
        for v in component:
            answer[v] = potential[v] ^ shift

    print(*answer)

