def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    k = int(data[0])
    s = data[1].decode()
    t = data[2].decode()
    n, m = len(s), len(t)

    if abs(n - m) > k:
        print("No")
        return

    # prev[d] is the greatest row coordinate i reachable with exactly
    # the current number of edits on diagonal d = i-j, after matching
    # as many equal characters as possible.
    def extend(i, d):
        j = i - d
        while i < n and 0 <= j < m and s[i] == t[j]:
            i += 1
            j += 1
        return i

    prev = {0: extend(0, 0)}
    if prev[0] >= n and prev[0] >= m:
        print("Yes")
        return

    for edits in range(1, k + 1):
        cur = {}
        for d in range(-edits, edits + 1):
            best = -1

            # substitution (or a matched diagonal step)
            x = prev.get(d)
            if x is not None:
                best = max(best, x + 1)
            # deletion from s
            x = prev.get(d - 1)
            if x is not None:
                best = max(best, x + 1)
            # insertion into s
            x = prev.get(d + 1)
            if x is not None:
                best = max(best, x)

            if best >= 0:
                x = extend(best, d)
                cur[d] = x
                if x >= n and x - d >= m:
                    print("Yes")
                    return
        prev = cur

    print("No")

