import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        limit = 10 ** digits

        # Sieve primes among all numbers having at most this many digits.
        prime = bytearray(b'\x01') * limit
        prime[0] = prime[1] = 0
        for p in range(2, int(limit ** 0.5) + 1):
            if prime[p]:
                prime[p * p:limit:p] = b'\x00' * (
                    (limit - 1 - p * p) // p + 1
                )

        if prime[n] or prime[m]:
            return -1

        inf = 10 ** 30
        distance = [inf] * limit
        distance[n] = n
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != distance[value]:
                continue
            if value == m:
                return cost

            text = str(value).zfill(digits)
            for pos, ch in enumerate(text):
                place = 10 ** (digits - 1 - pos)
                old_digit = ord(ch) - ord('0')
                for new_digit in (old_digit - 1, old_digit + 1):
                    if not (0 <= new_digit <= 9):
                        continue
                    # A leading zero would no longer be a number with the
                    # required number of digits.
                    if pos == 0 and new_digit == 0:
                        continue
                    nxt = value + (new_digit - old_digit) * place
                    if not prime[nxt] and cost + nxt < distance[nxt]:
                        distance[nxt] = cost + nxt
                        heapq.heappush(heap, (cost + nxt, nxt))

        return -1

