from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        mask = (1 << 64) - 1
        base = 911382323
        power = [1] * (n + 1)
        pref = [0] * (n + 1)
        for k, v in enumerate(nums):
            power[k + 1] = (power[k] * base) & mask
            pref[k + 1] = (pref[k] * base + v + 1) & mask

        def same(a, b, length):
            return ((pref[a + length] - pref[a] * power[length]) & mask) == \
                   ((pref[b + length] - pref[b] * power[length]) & mask)

        answer = 0
        for i in range(1, n - 1):
            first = (2 * i <= n and same(0, i, i))
            if first:
                answer += n - max(2 * i, i + 1)
            limit = (n - i) // 2
            for d in range(1, limit + 1):
                if same(i, i + d, d) and not (first and d >= i):
                    answer += 1
        return answer

