import sys


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]

    best_odd = -10**30
    best_even = -10**30

    for i, x in enumerate(a, 1):
        if i & 1:
            # A surviving element may start the final stack, or follow
            # a surviving subsequence ending at an even position.
            best_odd = max(best_odd, x + max(0, best_even))
        else:
            best_even = max(best_even, x + best_odd)

    answer = best_odd if n & 1 else max(0, best_even)
    print(answer)


if __name__ == "__main__":
    solve()

