from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)
        is_target = [False] * n
        for idx in targetIndices:
            is_target[idx] = True

        inf = n + 1
        # dp[j] is the minimum number of target characters used to
        # form pattern[:j] from the source prefix processed so far.
        dp = [inf] * (m + 1)
        dp[0] = 0
        for i, ch in enumerate(source):
            cost = 1 if is_target[i] else 0
            for j in range(min(m, i + 1), 0, -1):
                if ch == pattern[j - 1]:
                    candidate = dp[j - 1] + cost
                    if candidate < dp[j]:
                        dp[j] = candidate

        # Every target index not used by this embedding can be removed.
        return len(targetIndices) - dp[m]

