from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        reverse = [[] for _ in range(n)]
        weights = []
        for a, b, w in edges:
            reverse[b].append((a, w))
            weights.append(w)

        candidates = sorted(set(weights))

        def feasible(limit: int) -> bool:
            seen = [False] * n
            seen[0] = True
            stack = [0]
            reached = 1
            while stack:
                v = stack.pop()
                for u, w in reverse[v]:
                    if not seen[u] and w <= limit:
                        seen[u] = True
                        reached += 1
                        stack.append(u)
            return reached == n

        if not candidates or not feasible(candidates[-1]):
            return -1

        lo, hi = 0, len(candidates) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(candidates[mid]):
                hi = mid
            else:
                lo = mid + 1
        return candidates[lo]

