class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        inf = 10**30
        dp = [[inf] * 3 for _ in range(3)]

        # Initially, the two outside houses form the only pair.
        for left_color in range(3):
            for right_color in range(3):
                if left_color != right_color:
                    dp[left_color][right_color] = (
                        cost[0][left_color] + cost[n - 1][right_color]
                    )

        # Add pairs from the outside toward the center.  The state records
        # the colors of the previous (outer) left and right houses.
        for k in range(1, n // 2):
            ndp = [[inf] * 3 for _ in range(3)]
            left, right = k, n - 1 - k
            for old_left in range(3):
                for old_right in range(3):
                    cur = dp[old_left][old_right]
                    if cur == inf:
                        continue
                    for a in range(3):
                        if a == old_left:
                            continue
                        for b in range(3):
                            if b == old_right or b == a:
                                continue
                            value = cur + cost[left][a] + cost[right][b]
                            if value < ndp[a][b]:
                                ndp[a][b] = value
            dp = ndp

        return min(min(row) for row in dp)

