class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        initial = s.count('1')
        runs = []
        i = 0
        n = len(s)
        while i < n:
            j = i + 1
            while j < n and s[j] == s[i]:
                j += 1
            runs.append((s[i], j - i))
            i = j

        zero_lengths = [length for bit, length in runs if bit == '0']
        best_gain = 0
        shortest_eligible_one = None

        for i, (bit, length) in enumerate(runs):
            if (bit == '1' and i > 0 and i + 1 < len(runs)
                    and runs[i - 1][0] == '0' and runs[i + 1][0] == '0'):
                if shortest_eligible_one is None:
                    shortest_eligible_one = length
                else:
                    shortest_eligible_one = min(shortest_eligible_one, length)
                # Turning this run off merges its two neighboring zero runs;
                # flipping that merged run gains both neighboring lengths.
                best_gain = max(best_gain, runs[i - 1][1] + runs[i + 1][1])

        if shortest_eligible_one is None:
            return initial

        # Alternatively, flip any other zero run after paying for this one run.
        best_gain = max(best_gain, max(zero_lengths) - shortest_eligible_one)
        return initial + best_gain

